async function match(id){
 const [r,e,l]=await Promise.all([
  db.from("matches").select("*,home_team:teams!matches_home_team_id_fkey(name),away_team:teams!matches_away_team_id_fkey(name),leagues(name),competition_stages(name)").eq("id",id).single(),
  db.from("match_events").select("*,players:player_id(name),teams:team_id(name)").eq("match_id",id).order("minute").order("added_time"),
  db.from("match_lineups").select("*,team:teams!match_lineups_team_id_fkey(name),match_lineup_players(*,player:players!match_lineup_players_player_id_fkey(name))").eq("match_id",id)
 ]);
 if(r.error)return shell("Mechi",errBox(r.error));
 const render=()=>{
  const x=r.data, events=e.data||[], lineups=l.data||[];
  const normalEvents=events.filter(z=>!z.is_penalty_shootout); const shootoutEvents=events.filter(z=>z.is_penalty_shootout).sort((a,b)=>(a.shootout_order||0)-(b.shootout_order||0)); const ev=normalEvents.map(z=>'<div class="row"><span><b>'+esc(z.event_type)+'</b><small>'+esc(z.minute||"")+(z.added_time?"+ "+z.added_time:"")+"' · "+esc(z.players?.name||"")+'</small></span><span>'+esc(z.teams?.name||"")+'</span></div>').join("")||'<div class="empty">Hakuna events.</div>'; const homeShootout=shootoutEvents.filter(z=>z.team_id===x.home_team_id); const awayShootout=shootoutEvents.filter(z=>z.team_id===x.away_team_id); const shootoutList=(items)=>items.length?'<div class="list">'+items.map(z=>'<div class="row"><span><b>'+esc(z.shootout_order)+'. '+esc(z.players?.name||"")+'</b></span><strong class="penalty-result '+(z.shootout_result==="scored"?"penalty-scored":"penalty-missed")+'">'+(z.shootout_result==="scored"?"⚽ Amefunga":"✕ Amekosa")+'</strong></div>').join("")+'</div>':'<div class="empty">Hakuna penalty zilizorekodiwa.</div>'; const shootout=shootoutEvents.length?'<section class="card"><h2>Penalty Shootout</h2><div class="penalty-teams"><div class="penalty-team"><h3>'+esc(x.home_team?.name||"Timu ya Nyumbani")+'</h3>'+shootoutList(homeShootout)+'</div><div class="penalty-team"><h3>'+esc(x.away_team?.name||"Timu ya Ugenini")+'</h3>'+shootoutList(awayShootout)+'</div></div></section>':"";
  const lineupByTeam=(teamId)=>lineups.find(z=>z.team_id===teamId);
  const playerCard=(p,starter=true)=>{
   const name=p.player?.full_name||p.player?.name||"Mchezaji";
   const photo=p.player?.photo_url;
   return '<div class="pitch-player '+(starter?"":"bench-player")+'" style="left:'+Math.max(5,Math.min(95,Number(p.position_x??50)))+'%;top:'+Math.max(4,Math.min(96,Number(p.position_y??50)))+'%" title="'+esc(name)+'"><div class="pitch-player-photo">'+(photo?'<img src="'+esc(photo)+'" alt="'+esc(name)+'" loading="lazy">':'<span>👤</span>')+'</div><b>'+esc(name)+'</b>'+(p.position?'<small>'+esc(p.position)+'</small>':"")+'</div>';
  };
  const pitchPlayers=(teamId)=>{const lu=lineupByTeam(teamId);if(!lu)return "";return (lu.match_lineup_players||[]).filter(p=>p.starter).sort((a,b)=>(a.sort_order||0)-(b.sort_order||0)).map(p=>playerCard(p,true)).join("")};
  const benchBlock=(teamId,label)=>{const lu=lineupByTeam(teamId);if(!lu)return "";const bench=(lu.match_lineup_players||[]).filter(p=>!p.starter).sort((a,b)=>(a.sort_order||0)-(b.sort_order||0));return '<section class="bench-panel"><div class="bench-head"><div><span class="tag">AKIBA</span><h3>'+esc(label)+'</h3></div><span class="formation-badge">'+esc(lu.formation||"—")+'</span></div><div class="bench-list">'+(bench.map(p=>'<div class="bench-card">'+(p.player?.photo_url?'<img src="'+esc(p.player.photo_url)+'" alt="" loading="lazy">':'<div class="bench-photo">👤</div>')+'<span><b>'+esc(p.player?.full_name||p.player?.name||"Mchezaji")+'</b><small>'+esc(p.position||"Akiba")+'</small></span></div>').join("")||'<div class="empty">Hakuna wachezaji wa akiba.</div>')+'</div></section>'};
  const luHome=lineupByTeam(x.home_team_id),luAway=lineupByTeam(x.away_team_id);
  const lu=luHome||luAway?'<section class="lineup-visual card"><div class="lineup-title"><div><span class="tag">LINEUPS</span><h2>Mpangilio wa Wachezaji</h2></div></div><div class="pitch-wrap"><div class="pitch"><div class="pitch-lines"><div class="pitch-half"></div><div class="pitch-center-circle"></div><div class="pitch-center-dot"></div><div class="pitch-box pitch-box-top"></div><div class="pitch-box pitch-box-bottom"></div><div class="pitch-goal pitch-goal-top"></div><div class="pitch-goal pitch-goal-bottom"></div></div><div class="pitch-team-label pitch-away-label">'+esc(x.away_team?.name||"Away")+' <span>'+(luAway?esc(luAway.formation||""):"")+'</span></div><div class="pitch-team-label pitch-home-label">'+esc(x.home_team?.name||"Home")+' <span>'+(luHome?esc(luHome.formation||""):"")+'</span></div>'+pitchPlayers(x.away_team_id)+pitchPlayers(x.home_team_id)+'</div></div><div class="bench-grid">'+benchBlock(x.away_team_id,x.away_team?.name||"Away")+benchBlock(x.home_team_id,x.home_team?.name||"Home")+'</div></section>':'<section class="card"><h2>Lineups</h2><div class="empty">Lineups bado hazijawekwa.</div></section>';

  const timer=(x.status==="live"||x.status==="halftime")?'<div id="liveClock" class="tag">LIVE</div>':"";
  shell(esc(x.home_team?.name)+" vs "+esc(x.away_team?.name),'<div class="detail"><section class="card"><div class="tag">'+esc(x.status)+'</div><div class="score">'+esc(x.home_team?.name)+' <b>'+(x.home_score??0)+' — '+(x.away_score??0)+'</b> '+esc(x.away_team?.name)+'</div>'+timer+'<p>'+fmt(x.scheduled_at)+'</p><p>'+esc(x.leagues?.name||"")+' · '+esc(x.competition_stages?.name||x.round_name||"")+'</p></section><section class="card"><h2>Timeline</h2><div class="list">'+ev+'</div></section>'+shootout+'<section class="card"><h2>Lineups</h2><div class="cards">'+(lu||'<div class="empty">Lineups bado hazijawekwa.</div>')+'</div></section></div>');
 };
 render();
 const channel=db.channel("match-"+id).on("postgres_changes",{event:"*",schema:"public",table:"matches",filter:"id=eq."+id},()=>match(id)).on("postgres_changes",{event:"*",schema:"public",table:"match_events",filter:"match_id=eq."+id},()=>match(id)).on("postgres_changes",{event:"*",schema:"public",table:"match_lineups",filter:"match_id=eq."+id},()=>match(id)).subscribe();
 setTimeout(()=>db.removeChannel(channel),300000);
}

