 const refreshShootoutMatches=async()=>{const q=await db.from("matches").select("id,home_team_id,away_team_id,scheduled_at,status,home_score,away_score,home_team:teams!matches_home_team_id_fkey(name),away_team:teams!matches_away_team_id_fkey(name)").eq("status","finished").order("scheduled_at",{ascending:false}).limit(50);soMatch.innerHTML='<option value="">Chagua mechi iliyomalizika</option>'+(q.data||[]).map(x=>'<option value="'+x.id+'">'+esc(x.home_team?.name||"")+' '+x.home_score+' — '+x.away_score+' '+esc(x.away_team?.name||"")+' · '+fmt(x.scheduled_at)+'</option>').join("")};
